const {chromium}=require(process.env.MDO_PLAYWRIGHT_PATH || 'playwright');
const assert=require('node:assert/strict');
(async()=>{
 const origin=process.argv[2],evidence=process.argv[3],repository=process.argv[4],browser=await chromium.launch({headless:true,channel:'msedge'});
 let page;const errors=[],diagnostics=[];
 try{
  page=await browser.newPage({viewport:{width:1440,height:1000},locale:'zh-CN'});
  page.on('pageerror',error=>errors.push(String(error)));page.on('console',message=>{if(message.type()==='error')diagnostics.push(message.text());});
  await page.route('**/*',route=>new URL(route.request().url()).hostname==='127.0.0.1'?route.continue():route.abort());
  await page.goto(origin+'/');await page.waitForFunction(()=>Boolean(window.mdo));await page.locator('#new-workbench-tab').click();
  await page.getByRole('heading',{name:'新标签页',exact:true}).waitFor();
  await page.evaluate(repository=>mdo.panel.open({client:mdo.clientId,type:'mdo.changes',key:'git',params:{repository},reveal:'activate'}),repository);
  const view=page.locator('.wb-changes-view');await view.getByRole('textbox',{name:'筛选变更文件',exact:true}).waitFor();
  const filter=view.getByRole('textbox',{name:'筛选变更文件',exact:true});
  const file=async path=>{await filter.fill(path);await view.getByRole('treeitem').filter({hasText:path}).click();};
  await view.locator('.wb-changes-summary').filter({hasText:'455 文件'}).waitFor();
  assert.ok(await view.getByRole('treeitem').count()<80,'change tree must be virtualized');
  await file('recreated.txt');await view.locator('.wb-change-added').filter({hasText:'after recreation'}).waitFor();
  assert.equal(await view.getByRole('treeitem').count(),1,'staged deletion plus recreation must be one worktree entry');
  assert.equal(await view.getByRole('button',{name:'打开工作区文件',exact:true}).isDisabled(),false);
  await file('tracked.js');await view.locator('.wb-change-added').filter({hasText:'3; // working'}).waitFor();
  await view.getByRole('combobox',{name:'变更比较范围',exact:true}).selectOption('staged');
  await view.locator('.wb-change-added').filter({hasText:'2; // staged'}).waitFor();
  assert.equal(await view.locator('.wb-change-code').filter({hasText:'3; // working'}).count(),0);
  await view.getByRole('combobox',{name:'变更比较范围',exact:true}).selectOption('unstaged');
  await view.locator('.wb-change-removed').filter({hasText:'2; // staged'}).waitFor();
  await view.getByRole('button',{name:'变更更多操作',exact:true}).click();await page.getByRole('menuitemcheckbox',{name:'左右对照',exact:true}).click();
  assert.equal(await view.locator('.wb-changes-diff').getAttribute('data-split'),'true');
  const old=view.locator('.wb-change-removed').filter({hasText:'2; // staged'}),fresh=view.locator('.wb-change-added').filter({hasText:'3; // working'});
  assert.ok((await old.boundingBox()).x<(await fresh.boundingBox()).x);
  await fresh.getByRole('button').click();await view.getByRole('button',{name:'引用所选差异',exact:true}).click();
  const quoted=await page.locator('.prompt-context-open').getAttribute('title');
  assert.ok(quoted.includes('比较范围：未暂存')&&quoted.includes('比较修订：')&&quoted.includes('+const answer = 3; // working'),quoted);
  await view.getByRole('button',{name:'打开工作区文件',exact:true}).click();
  await page.locator('.wb-files-view:not([hidden]) .wb-source-text').filter({hasText:'3; // working'}).waitFor();
  await page.getByRole('tab',{name:'变更',exact:true}).click();
  await view.getByRole('combobox',{name:'变更比较范围',exact:true}).selectOption('workspace');
  await file('large.txt');await view.locator('.wb-file-info').filter({hasText:'/ 5,205'}).waitFor();
  await view.getByRole('button',{name:'下一页差异',exact:true}).click();
  await view.locator('.wb-file-info').filter({hasText:'301–600'}).waitFor();
  await view.getByRole('button',{name:'上一页差异',exact:true}).click();await view.locator('.wb-file-info').filter({hasText:'1–300'}).waitFor();
  page.once('dialog',dialog=>dialog.accept('5200'));
  await view.getByRole('button',{name:'变更更多操作',exact:true}).click();await page.getByRole('menuitem',{name:'跳到差异行…',exact:true}).click();
  await view.locator('.wb-change-code').filter({hasText:'new line 2599'}).waitFor();
  await page.screenshot({path:evidence+'/changes-split.png'});
  await file('binary.dat');await view.getByText('二进制文件无法显示文本差异',{exact:true}).waitFor();
  await view.getByRole('combobox',{name:'变更比较范围',exact:true}).selectOption('branch');
  await view.getByRole('combobox',{name:'比较基准分支',exact:true}).selectOption('refs/heads/baseline');
  await filter.fill('');await view.getByRole('treeitem').filter({hasText:'branch.txt'}).waitFor();await view.locator('.wb-change-added').filter({hasText:'committed'}).waitFor();
  assert.equal(await view.getByRole('treeitem').count(),2);
  await view.getByRole('combobox',{name:'变更比较范围',exact:true}).selectOption('session');
  await view.getByText('这个会话没有已捕获的比较基线。请选择工作区或分支比较。',{exact:true}).waitFor();
  await view.getByRole('combobox',{name:'变更比较范围',exact:true}).selectOption('workspace');await file('large.txt');
  await view.locator('.wb-file-info').filter({hasText:'1–300'}).waitFor();
  await page.evaluate(path=>mdo.files.write({space:'native',path,text:'external replacement\n'}),repository+'/large.txt');
  await view.getByRole('button',{name:'下一页差异',exact:true}).click();await view.getByRole('button',{name:'重新读取变更',exact:true}).waitFor();
  assert.equal(await view.locator('.wb-change-code').count(),0,'stale diffs must not remain mixed with another revision');
  await view.getByRole('button',{name:'重新读取变更',exact:true}).click();await view.locator('.wb-file-info').filter({hasText:'1–300 / 2,606'}).waitFor();
  page.once('dialog',dialog=>dialog.accept('2600'));
  await view.getByRole('button',{name:'变更更多操作',exact:true}).click();await page.getByRole('menuitem',{name:'跳到差异行…',exact:true}).click();
  await view.locator('.wb-change-code').filter({hasText:'external replacement'}).waitFor();
  await page.setViewportSize({width:390,height:844});await page.waitForTimeout(400);
  const mobile=await view.boundingBox();assert.ok(mobile.width>300&&mobile.width<=391&&mobile.x>=-1,JSON.stringify(mobile));
  assert.equal(await view.locator('.wb-file-tree').isVisible(),false);
  await page.screenshot({path:evidence+'/changes-mobile.png'});
  await page.reload();await page.waitForFunction(()=>Boolean(window.mdo));await page.locator('.wb-changes-view:not([hidden])').waitFor();
  assert.deepEqual(errors,[]);require('node:fs').writeFileSync(evidence+'/result.json',JSON.stringify({passed:true,time:new Date().toISOString(),checks:['scopes','staged deletion and recreation','paged large diffs','paired identities','virtual tree','quote provenance','file location','binary','branch','stale revision','mobile','reload']},null,2));console.log('Git workbench actual UI: scopes, paged large diffs, side-by-side identities, virtual tree, quotes/file location, binary, branch and stale revision recovery: PASS');
 }catch(error){console.error({errors,diagnostics});require('node:fs').writeFileSync(evidence+'/failure-diagnostics.json',JSON.stringify({errors,diagnostics},null,2));if(page)await page.screenshot({path:evidence+'/failure.png'}).catch(()=>{});throw error;}
 finally{await browser.close();}
})().catch(error=>{console.error(error);process.exitCode=1;});
